180 |     /// @dev Update cache and, on the first call per block, ratio accumulators
181 |     function _update(uint128 baseBalance, uint128 fyBalance, uint112 _baseCached, uint112 _fyTokenCached) private {
182 |         uint32 blockTimestamp = uint32(block.timestamp);
183 |         uint32 timeElapsed = blockTimestamp - blockTimestampLast; // overflow is desired
184 |         if (timeElapsed > 0 && _baseCached != 0 && _fyTokenCached != 0) {
185 |             uint256 scaledFYTokenCached = uint256(_fyTokenCached) * 1e27;
186 |             cumulativeBalancesRatio += scaledFYTokenCached / _baseCached * timeElapsed;
187 |         }
188 |         baseCached = baseBalance.u112();
189 |         fyTokenCached = fyBalance.u112();
190 |         blockTimestampLast = blockTimestamp;
191 |         emit Sync(baseCached, fyTokenCached, cumulativeBalancesRatio);
192 |     }
